sql.workQueue.getProcessStepsByTypeId:
select ps.id as process_step_id, p.project_name, pps.id as project_process_step_id, wqt.work_queue_type, st.abbreviation as state_abbreviation, wqt.id as work_queue_type_id, pswqt.id as process_step_work_queue_type_id, pps.project_id, ps.process_step_name, p.company_project_status_type_id, DATE_PART('day', now() - pps.date_created) as days_in_queue, cpst.project_status_type_id, p.contact_id, case when u.id is not null then concat(u.first_name, ' ', u.last_name) end AS owner, coalesce(pps.date_modified, pps.date_created) as last_updated, coalesce(( SELECT array_to_json(array_agg(row_to_json(owningPositions))) FROM ( SELECT pspop.id, pspop.process_step_process_id as "processStepProcessId", pspop.position_id as "positionId", pspop.archived FROM flow.process_step_process_owning_position pspop inner join flow.process_step_process psp on psp.id = pspop.process_step_process_id WHERE psp.process_step_id = ps.id and pspop.archived is not true) owningPositions), '[]') AS "owningPositions", coalesce(( SELECT array_to_json(array_agg(row_to_json(activeProcessSteps))) FROM ( select ps2.process_step_name as "processStepName", ps2.id as "processStepId" from flow.project_process_step pps2 inner join flow.process_step ps2 on ps2.id = pps2.process_step_id inner join flow.company_process_step_status_type cpsst2 on cpsst2.id = pps2.company_process_step_status_type_id inner join flow.process_step_status_type psst2 on psst2.id = cpsst2.process_step_status_type_id where pps2.project_id = p.id and cpsst2.process_step_status_type_id = 1 and pps2.archived is not true and pps2.id != pps.id order by ps2.process_step_name) activeProcessSteps), '[]') AS "activeProcessSteps", coalesce(( SELECT array_to_json(array_agg(row_to_json(notes))) FROM ( select n.id, n.note, n.archived, n.parent_id as "parentId", n.date_created as "dateCreated", n.date_modified as "dateModified", n.created_by_id as "createdById", concat(creator.first_name, ' ', creator.last_name) as "createdBy", n.modified_by_id as "modifiedById", pn.project_process_step_id as "projectProcessStepId", pn.process_step_work_queue_type_id as "processStepWorkQueueTypeId", coalesce(( SELECT array_to_json(array_agg(row_to_json(childNotes))) FROM ( select n2.id, n2.note, n2.archived, n2.date_created as "dateCreated", n2.date_modified as "dateModified", n2.created_by_id as "createdById", concat(creator2.first_name, ' ', creator2.last_name) as "createdBy", n2.modified_by_id as "modifiedById", pn2.project_process_step_id as "projectProcessStepId", pn2.process_step_work_queue_type_id as "processStepWorkQueueTypeId" from flow.note n2 inner join flow.project_process_step_process_step_work_queue_type_note pn2 on pn2.note_id = n2.id inner join flow.user creator2 on creator2.id = n2.created_by_id where n2.archived is not true and n2.parent_id = n.id order by n2.date_created ) childNotes), '[]') AS "childNotes" from flow.note n inner join flow.project_process_step_process_step_work_queue_type_note pn on pn.note_id = n.id inner join flow.user creator on creator.id = n.created_by_id where n.archived is not true and n.parent_id is null and pn.project_process_step_id = pps.id and pn.process_step_work_queue_type_id = pswqt.id order by n.date_created desc
) notes), '[]') AS "notes" from flow.project p inner join flow.company_process cp on cp.id = p.company_process_id inner join flow.project_process_step pps on pps.project_id = p.id inner join flow.company_project_status_type cpst on cpst.id = p.company_project_status_type_id inner join flow.process_step ps on ps.id = pps.process_step_id inner join flow.process_step_work_queue_type pswqt on pswqt.process_step_id = ps.id inner join flow.work_queue_type wqt on wqt.id = pswqt.work_queue_type_id inner join flow.company_process_step_status_type cpsst on cpsst.id = pps.company_process_step_status_type_id left join flow.company_state cs on cs.id = p.company_state_id left join flow.state st on st.id = cs.state_id left join flow.user_position up on up.id = pps.user_position_id left join flow.user u on u.id = up.user_id where pswqt.work_queue_type_id = :workQueueTypeId and pswqt.archived is not true and pps.archived is not true and case when :isParent then ps.company_id = any (select id from flow.company_hierarchy_filter_down(:parentCompanyId::int)) else ps.company_id = :companyId end
and cpsst.process_step_status_type_id in (:processStepStatusTypeIds) and (p.company_project_status_type_id = any( select pswqtpst.company_project_status_type_id from flow.process_step_work_queue_type_project_status_type pswqtpst where pswqtpst.process_step_work_queue_type_id = pswqt.id and pswqtpst.archived is not true ) OR (cpst.project_status_type_id = any( select pswqtpst.project_status_type_id from flow.process_step_work_queue_type_project_status_type pswqtpst where pswqtpst.process_step_work_queue_type_id = pswqt.id and pswqtpst.archived is not true ))) order by pps.date_created limit :limit offset :offset

sql.workQueue.getProcessStepsByTypeIdForHack:
select ps.id as process_step_id, p.id as project_id, pps2.id as pps2_id, p.project_name, pps.id as project_process_step_id, coalesce(ppscfv.timestamp_value, ppscfv3.timestamp_value) as proposal_due_date, wqt.work_queue_type, st.abbreviation as state_abbreviation, wqt.id as work_queue_type_id, pswqt.id as process_step_work_queue_type_id, pps.project_id, ps.process_step_name, p.company_project_status_type_id, DATE_PART('day', now() - pps.date_created) as days_in_queue, cpst.project_status_type_id, p.contact_id, case when u.id is not null then concat(u.first_name, ' ', u.last_name) end AS owner, coalesce(pps.date_modified, pps.date_created) as last_updated, coalesce(( SELECT array_to_json(array_agg(row_to_json(owningPositions))) FROM ( SELECT pspop.id, pspop.process_step_process_id as "processStepProcessId", pspop.position_id as "positionId", pspop.archived FROM flow.process_step_process_owning_position pspop inner join flow.process_step_process psp on psp.id = pspop.process_step_process_id WHERE psp.process_step_id = ps.id and pspop.archived is not true) owningPositions), '[]') AS "owningPositions", coalesce(( SELECT array_to_json(array_agg(row_to_json(activeProcessSteps))) FROM ( select ps2.process_step_name as "processStepName", ps2.id as "processStepId" from flow.project_process_step pps2 inner join flow.process_step ps2 on ps2.id = pps2.process_step_id inner join flow.company_process_step_status_type cpsst2 on cpsst2.id = pps2.company_process_step_status_type_id inner join flow.process_step_status_type psst2 on psst2.id = cpsst2.process_step_status_type_id where pps2.project_id = p.id and cpsst2.process_step_status_type_id = 1 and pps2.archived is not true and pps2.id != pps.id order by ps2.process_step_name) activeProcessSteps), '[]') AS "activeProcessSteps", coalesce(( SELECT array_to_json(array_agg(row_to_json(notes))) FROM ( select n.id, n.note, n.archived, n.parent_id as "parentId", n.date_created as "dateCreated", n.date_modified as "dateModified", n.created_by_id as "createdById", concat(creator.first_name, ' ', creator.last_name) as "createdBy", n.modified_by_id as "modifiedById", pn.project_process_step_id as "projectProcessStepId", pn.process_step_work_queue_type_id as "processStepWorkQueueTypeId", coalesce(( SELECT array_to_json(array_agg(row_to_json(childNotes))) FROM ( select n2.id, n2.note, n2.archived, n2.date_created as "dateCreated", n2.date_modified as "dateModified", n2.created_by_id as "createdById", concat(creator2.first_name, ' ', creator2.last_name) as "createdBy", n2.modified_by_id as "modifiedById", pn2.project_process_step_id as "projectProcessStepId", pn2.process_step_work_queue_type_id as "processStepWorkQueueTypeId" from flow.note n2 inner join flow.project_process_step_process_step_work_queue_type_note pn2 on pn2.note_id = n2.id inner join flow.user creator2 on creator2.id = n2.created_by_id where n2.archived is not true and n2.parent_id = n.id order by n2.date_created ) childNotes), '[]') AS "childNotes" from flow.note n inner join flow.project_process_step_process_step_work_queue_type_note pn on pn.note_id = n.id inner join flow.user creator on creator.id = n.created_by_id where n.archived is not true and n.parent_id is null and pn.project_process_step_id = pps.id and pn.process_step_work_queue_type_id = pswqt.id order by n.date_created desc
) notes), '[]') AS "notes" from flow.project p inner join flow.company_process cp on cp.id = p.company_process_id inner join flow.project_process_step pps on pps.project_id = p.id inner join flow.company_project_status_type cpst on cpst.id = p.company_project_status_type_id inner join flow.process_step ps on ps.id = pps.process_step_id inner join flow.process_step_work_queue_type pswqt on pswqt.process_step_id = ps.id inner join flow.work_queue_type wqt on wqt.id = pswqt.work_queue_type_id inner join flow.company_process_step_status_type cpsst on cpsst.id = pps.company_process_step_status_type_id left join flow.project_process_step pps2 on pps2.project_id = p.id and pps2.process_step_id = 1 and pps2.main is true left join flow.project_process_step_custom_field_value ppscfv on pps2.id = ppscfv.project_process_step_id and ppscfv.custom_field_group_assignment_id = 5 left join flow.project_process_step pps3 on pps3.project_id = p.id and pps3.process_step_id in (247,249,251,252,250) and pps3.main is true left join flow.project_process_step_custom_field_value ppscfv3 on pps3.id = ppscfv3.project_process_step_id and ppscfv3.custom_field_group_assignment_id in (17263, 17349, 17350, 17351, 17352) left join flow.company_state cs on cs.id = p.company_state_id left join flow.state st on st.id = cs.state_id left join flow.user_position up on up.id = pps.user_position_id left join flow.user u on u.id = up.user_id where pswqt.work_queue_type_id = :workQueueTypeId and pswqt.archived is not true and pps.archived is not true and case when :isParent then ps.company_id = any (select id from flow.company_hierarchy_filter_down(:parentCompanyId::int)) else ps.company_id = :companyId end
and cpsst.process_step_status_type_id in (:processStepStatusTypeIds) and (p.company_project_status_type_id = any( select pswqtpst.company_project_status_type_id from flow.process_step_work_queue_type_project_status_type pswqtpst where pswqtpst.process_step_work_queue_type_id = pswqt.id and pswqtpst.archived is not true ) OR (cpst.project_status_type_id = any( select pswqtpst.project_status_type_id from flow.process_step_work_queue_type_project_status_type pswqtpst where pswqtpst.process_step_work_queue_type_id = pswqt.id and pswqtpst.archived is not true ))) order by coalesce(ppscfv.timestamp_value, ppscfv3.timestamp_value) nulls last limit :limit offset :offset
